from (values
  ('ramayana-popular-lakshman-rekha-v1', 'exile_reception', 1, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_POPULAR_LIVING_BRIDGES_DB_V1","expectationId":"popular-lakshman-rekha","storyId":"ramayana-popular-lakshman-rekha-v1","sourceFamily":"popular_performance_and_adaptation_reception","sourceRefs":["ramayana-dutt-selected-inventory","sagar-ramayan-series"],"selectedExpressionRelation":"The selected Dutt sequence contains Maricha''s cry, Sita''s urgent demand, Lakshmana''s departure, Ravana''s disguise, and the abduction, but not the familiar drawn-line device.","alignmentNote":"The pack tells the complete familiar line story without claiming a single ancient textual origin or importing television dialogue."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["sita","lakshmana","rama","maricha","ravana"],"places":["panchavati-hut","panchavati-forest"],"relationships":[{"target_kind":"story_cycle","target_id":"golden-deer-plot","relationship":"popularly_expands_departure_from","inverse_relationship":"has_later_reception_expansion","bidirectional":true},{"target_kind":"story_cycle","target_id":"sita-is-taken","relationship":"popularly_precedes","inverse_relationship":"has_popular_line_preceding","bidirectional":true},{"target_kind":"entity","target_id":"sita","relationship":"centres_decision_of","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"lakshmana","relationship":"centres_departure_of","inverse_relationship":"appears_in","bidirectional":true}],"expressionScope":"Audience-familiar later performance and adaptation story placed beside, not inside, the selected Dutt golden-deer and abduction sequence."}'::jsonb),
  ('ramayana-popular-shabari-tasted-berries-v1', 'exile_reception', 2, 2, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_POPULAR_LIVING_BRIDGES_DB_V1","expectationId":"popular-shabari-tasted-berries","storyId":"ramayana-popular-shabari-tasted-berries-v1","sourceFamily":"popular_devotional_reception_beside_selected_hospitality_scene","sourceRefs":["ramayana-dutt-selected-inventory","sagar-ramayan-series"],"selectedExpressionRelation":"The selected Dutt expression includes Shabari''s long-awaited welcome and gathered forest food; the tasting of each berry is treated here as a later familiar devotional motif.","alignmentNote":"The narration preserves the motif''s devotional meaning while refusing caste humiliation, hygiene instruction, or invented script dialogue."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["shabari","rama","lakshmana","matanga"],"places":["shabari-hermitage","pampa-region"],"relationships":[{"target_kind":"story_cycle","target_id":"toward-pampa","relationship":"popularly_expands_welcome_within","inverse_relationship":"has_devotional_reception_expansion","bidirectional":true},{"target_kind":"story_cycle","target_id":"hanuman-meets-rama","relationship":"prepares_route_toward","inverse_relationship":"follows_shabari_guidance","bidirectional":true},{"target_kind":"entity","target_id":"shabari","relationship":"centres_devotion_of","inverse_relationship":"appears_in","bidirectional":true},{"target_kind":"entity","target_id":"rama","relationship":"welcomes","inverse_relationship":"is_welcomed_in","bidirectional":true}],"expressionScope":"Popular devotional and adaptation expansion of Shabari''s source-grounded welcome and gathered-food scene."}'::jsonb),
  ('ramayana-regional-bridge-squirrel-v1', 'bridge_reception', 3, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_POPULAR_LIVING_BRIDGES_DB_V1","expectationId":"regional-bridge-squirrel","storyId":"ramayana-regional-bridge-squirrel-v1","sourceFamily":"regional_telling_and_popular_visual_reception","sourceRefs":["ramayana-dutt-selected-inventory","ucpress-many-ramayanas-squirrel"],"selectedExpressionRelation":"The selected Dutt expression gives Nala and the vanara force the bridge-building action; the squirrel is a separately labelled regional and popular addition.","alignmentNote":"The complete small-helper story is retained without presenting its body stripes, divine touch, or exact dialogue as universal textual history."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["rama","nala","hanuman","squirrel","vanara-builders"],"places":["ocean-shore","setu-building-ground","rameswaram-living"],"relationships":[{"target_kind":"story_cycle","target_id":"ocean-and-bridge","relationship":"regionally_expands_building_within","inverse_relationship":"has_regional_small_helper_story","bidirectional":true},{"target_kind":"entity","target_id":"nala","relationship":"joins_work_led_by","inverse_relationship":"receives_small_helper_in_reception","bidirectional":true},{"target_kind":"entity","target_id":"rama","relationship":"receives_recognition_from","inverse_relationship":"recognizes_service_in","bidirectional":true},{"target_kind":"story","target_id":"ramayana-living-rameswaram-linga-tradition-v1","relationship":"opens_living_rameswaram_world","inverse_relationship":"returns_to_bridge_reception","bidirectional":true}],"expressionScope":"Regional and popular devotional bridge-building story placed beside the selected Nala-led ocean bridge sequence."}'::jsonb),
  ('ramayana-living-rameswaram-linga-tradition-v1', 'living_afterlife', 4, 1, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_POPULAR_LIVING_BRIDGES_DB_V1","expectationId":"living-rameswaram-linga-tradition","storyId":"ramayana-living-rameswaram-linga-tradition-v1","sourceFamily":"living_temple_origin_tradition_and_current_official_place_record","sourceRefs":["incredible-india-ramanathaswamy-temple","tnhrce-ramanathaswamy-temple","devam-ramayana-living-world-records"],"selectedExpressionRelation":"The selected Dutt expression supplies the ocean bridge and return geography; the linga-installation and worship-order story is a separately governed living Rameswaram temple tradition.","alignmentNote":"The story follows the official tourism account''s Ramalingam, Hanuman-brought Vishvalingam, and remembered first-worship order while treating them as legend and current tradition rather than epic or archaeological proof."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["rama","sita","lakshmana","hanuman","shiva"],"places":["rameswaram-living","ramanathaswamy-temple","ocean-shore","kailash-tradition"],"relationships":[{"target_kind":"story_cycle","target_id":"ocean-and-bridge","relationship":"shares_sacred_coast_with","inverse_relationship":"opens_living_temple_tradition","bidirectional":true},{"target_kind":"story_cycle","target_id":"road-home","relationship":"living_tradition_places_worship_around_return","inverse_relationship":"opens_rameswaram_return_tradition","bidirectional":true},{"target_kind":"entity","target_id":"shiva","relationship":"centres_worship_of","inverse_relationship":"is_worshipped_in","bidirectional":true},{"target_kind":"entity","target_id":"hanuman","relationship":"remembers_service_of","inverse_relationship":"serves_in","bidirectional":true},{"target_kind":"story","target_id":"ramayana-regional-bridge-squirrel-v1","relationship":"returns_to_bridge_reception","inverse_relationship":"opens_living_rameswaram_world","bidirectional":true},{"target_kind":"living_place","target_id":"rameswaram-living","relationship":"continues_as","inverse_relationship":"hosts_tradition_of","bidirectional":true},{"target_kind":"temple","target_id":"ramanathaswamy-temple","relationship":"centres_current_institution","inverse_relationship":"carries_tradition_of","bidirectional":true}],"expressionScope":"Living Ramanathaswamy Temple tradition and official current-place context connected to, but not collapsed into, the selected epic bridge and return sequences."}'::jsonb),
  ('ramayana-living-diwali-rama-homecoming-v1', 'living_afterlife', 5, 2, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_POPULAR_LIVING_BRIDGES_DB_V1","expectationId":"living-diwali-rama-homecoming","storyId":"ramayana-living-diwali-rama-homecoming-v1","sourceFamily":"selected_epic_return_plus_current_multi_regional_festival_context","sourceRefs":["ramayana-dutt-selected-inventory","incredible-india-diwali","devam-ramayana-living-world-records"],"selectedExpressionRelation":"The selected Dutt expression supplies the complete Lanka-to-Ayodhya return and coronation sequence. The lamp-lit Diwali association is a separately labelled living festival memory.","alignmentNote":"The story makes the homecoming lane complete while preserving Jain, Sikh, Shakta, Vaishnava, regional-new-year, harvest, trade, Naraka, Lakshmi, Kali, Govardhan, and sibling observances as separate connected worlds."}'::jsonb, '{"readiness":"consumer_complete_en_hi","characters":["rama","sita","lakshmana","hanuman","bharata","shatrughna","ayodhya-citizens"],"places":["lanka","sky-road","bharadvaja-hermitage","nandigrama","ayodhya-living"],"relationships":[{"target_kind":"story_cycle","target_id":"road-home","relationship":"living_festival_remembers","inverse_relationship":"opens_living_diwali_association","bidirectional":true},{"target_kind":"story_cycle","target_id":"companions-depart","relationship":"continues_after_coronation_toward","inverse_relationship":"follows_homecoming_festival_memory","bidirectional":true},{"target_kind":"entity","target_id":"rama","relationship":"celebrates_return_of","inverse_relationship":"is_remembered_by","bidirectional":true},{"target_kind":"entity","target_id":"sita","relationship":"celebrates_return_of","inverse_relationship":"is_remembered_by","bidirectional":true},{"target_kind":"living_place","target_id":"ayodhya-living","relationship":"continues_in","inverse_relationship":"hosts_memory_of","bidirectional":true},{"target_kind":"festival","target_id":"diwali-rama-homecoming","relationship":"continues_as","inverse_relationship":"remembers_story_of","bidirectional":true}],"expressionScope":"One major North Indian and Ayodhya-centred living Diwali association connected to the selected epic return, alongside rather than above other Diwali traditions."}'::jsonb)
) as source(slug, arc_slug, backbone_ordinal, turn_ordinal, source_range, visual_direction)
